import java.util.*;

class Solution {
  private static final int MOD = 1_000_000_007;

  public int[] pathsWithMaxScore(List<String> board) {
    int n = board.size();
    int[][] best = new int[n][n];
    int[][] ways = new int[n][n];
    for (int[] row : best) Arrays.fill(row, -1);
    best[n - 1][n - 1] = 0;
    ways[n - 1][n - 1] = 1;
    for (int r = n - 1; r >= 0; r--) {
      for (int c = n - 1; c >= 0; c--) {
        if (board.get(r).charAt(c) == 'X' || (r == n - 1 && c == n - 1)) continue;
        int value = -1, count = 0;
        if (r + 1 < n && best[r + 1][c] >= 0) {
          value = best[r + 1][c];
          count = ways[r + 1][c];
        }
        if (c + 1 < n && best[r][c + 1] > value) {
          value = best[r][c + 1];
          count = ways[r][c + 1];
        } else if (c + 1 < n && best[r][c + 1] == value && value >= 0)
          count = (count + ways[r][c + 1]) % MOD;
        if (value >= 0) {
          best[r][c] =
              value
                  + (Character.isDigit(board.get(r).charAt(c)) ? board.get(r).charAt(c) - '0' : 0);
          ways[r][c] = count;
        }
      }
    }
    return best[0][0] < 0 ? new int[] {0, 0} : new int[] {best[0][0], ways[0][0]};
  }
}
